.sample-queries {
    margin-top: 16px;
}

.samples-label {
    font-size: 0.85rem;
    color: #86868b;
    margin-bottom: 8px;
}

.sample-list {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.sample-chip {
    background: #f5f5f7;
    border: 1px solid #d2d2d7;
    padding: 6px 12px;
