    // Anserini
    elements.anseriniStatus.textContent = status.anserini_jar_available ? `v${status.anserini_version}` : 'Not found';
    elements.anseriniStatus.className = 'status-value ' + (status.anserini_jar_available ? 'ok' : 'error');

