    } catch (error) {
        showError(elements.evalError, 'Rerun failed: ' + error.message);
    } finally {
        appState.isEvaluating = false;
        elements.runEvalBtn.disabled = false;
        elements.rerunEvalBtn.disabled = false;
        elements.evalLoading.classList.add('hidden');
    }
}

