'use client';

import { FormEvent, useEffect, useMemo, useState } from 'react';
import devQueries from '../src/data/msmarco-passage-dev-queries.json';

type QuerySample = {
  id: string;
  title: string;
};

type SearchResult = {
  docid?: string;
  score?: number;
  rank?: number;
  doc?: string;
};

type SearchState = {
  status: 'idle' | 'loading' | 'success' | 'error' | 'empty';
  message?: string;
  detail?: string;
  searchedQuery?: string;
  results: SearchResult[];
};

const SAMPLE_COUNT = 8;
const HITS = 10;
const allSamples = devQueries as QuerySample[];

function drawSamples(count = SAMPLE_COUNT) {
  const pool = [...allSamples];
  const samples: QuerySample[] = [];

  while (samples.length < count && pool.length > 0) {
    const index = Math.floor(Math.random() * pool.length);
    const [sample] = pool.splice(index, 1);
    samples.push(sample);
  }

  return samples;
}

function cleanPassage(doc?: string) {
  if (!doc) return 'No stored passage text was returned for this result.';

  return doc
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

export default function Home() {
  const [query, setQuery] = useState('');
  const [samples, setSamples] = useState<QuerySample[]>([]);
  const [state, setState] = useState<SearchState>({ status: 'idle', results: [] });

  const sampleCountLabel = useMemo(() => allSamples.length.toLocaleString(), []);

  useEffect(() => {
    setSamples(drawSamples());
  }, []);

  async function runSearch(nextQuery: string) {
    const trimmed = nextQuery.trim();
    setQuery(nextQuery);

    if (!trimmed) {
      setState({
        status: 'empty',
        message: 'Please enter a query or choose one of the MS MARCO dev queries below.',
        results: [],
      });
      return;
    }

    setState({ status: 'loading', searchedQuery: trimmed, results: [] });

    try {
      const response = await fetch(`/api/search?q=${encodeURIComponent(trimmed)}&hits=${HITS}`);
      const data = await response.json();

      if (!response.ok) {
        setState({
          status: 'error',
          message: data.error || 'Search failed.',
          detail: data.detail,
          searchedQuery: trimmed,
          results: [],
        });
        return;
      }

      const results = Array.isArray(data.candidates) ? data.candidates : [];
      setState({
        status: results.length > 0 ? 'success' : 'empty',
        message: results.length > 0 ? undefined : 'No passages matched this query.',
        searchedQuery: data.query || trimmed,
        results,
      });
    } catch (error) {
      setState({
        status: 'error',
        message: 'The frontend could not complete the search request.',
        detail: error instanceof Error ? error.message : undefined,
        searchedQuery: trimmed,
        results: [],
      });
    }
  }

  function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    runSearch(query);
  }

  return (
    <main className="page">
      <section className="hero">
        <p className="eyebrow">Anserini REST + Next.js</p>
        <h1>MS MARCO passage search</h1>
        <p className="subtitle">
          Search the MS MARCO passage corpus using the local Anserini REST API. Try a query from the
          dev set or enter your own to view ranked passages.
        </p>
      </section>

      <section className="search-card" aria-label="Search MS MARCO passages">
        <form className="search-form" onSubmit={onSubmit}>
          <input
            className="search-input"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="e.g. what is a lobster roll"
            aria-label="Search query"
          />
          <button className="primary-button" type="submit" disabled={state.status === 'loading'}>
            {state.status === 'loading' ? 'Searching…' : 'Search'}
          </button>
        </form>

        <div className="samples">
          <div className="samples-header">
            <p className="samples-title">Random MS MARCO passage dev queries</p>
            <button className="secondary-button" type="button" onClick={() => setSamples(drawSamples())}>
              Shuffle from {sampleCountLabel}
            </button>
          </div>
          <div className="sample-list">
            {samples.length === 0 && <span className="sample-placeholder">Loading sample queries…</span>}
            {samples.map((sample) => (
              <button
                className="sample-chip"
                key={sample.id}
                type="button"
                onClick={() => runSearch(sample.title)}
                disabled={state.status === 'loading'}
              >
                {sample.title}
              </button>
            ))}
          </div>
        </div>
      </section>

      {state.status === 'idle' && (
        <div className="status">Submit a query to retrieve ranked passages from msmarco-v1-passage.</div>
      )}

      {(state.status === 'empty' || state.status === 'error') && (
        <div className={`status ${state.status === 'error' ? 'error' : ''}`}>
          <strong>{state.message}</strong>
          {state.detail && <div>{state.detail}</div>}
        </div>
      )}

      {state.status === 'loading' && <div className="status">Searching Anserini for “{state.searchedQuery}”…</div>}

      {state.status === 'success' && (
        <section className="results-card" aria-live="polite">
          <div className="results-header">
            <h2 className="results-title">Ranked results</h2>
            <p className="results-meta">
              {state.results.length} hits for “{state.searchedQuery}”
            </p>
          </div>
          <ol className="result-list">
            {state.results.map((result, index) => (
              <li className="result-item" key={`${result.docid || 'doc'}-${result.rank || index}`}>
                <div className="result-topline">
                  <span className="rank">Rank {result.rank ?? index + 1}</span>
                  {typeof result.score === 'number' && <span className="score">Score {result.score.toFixed(4)}</span>}
                </div>
                <p className="docid">Document {result.docid || 'unknown'}</p>
                <p className="passage">{cleanPassage(result.doc)}</p>
              </li>
            ))}
          </ol>
        </section>
      )}
    </main>
  );
}

{
  "name": "msmarco-passage-search-app",
  "version": "0.1.0",
  "private": true,
  "scripts": {
    "dev": "next dev -p ${FRONTEND_PORT:-3000}",
    "build": "next build",
    "start": "next start -p ${FRONTEND_PORT:-3000}",
    "backend": "bash scripts/start-anserini-rest.sh",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "next": "^16.2.6",
    "react": "^19.2.6",
    "react-dom": "^19.2.6"
  },
  "devDependencies": {
    "@types/node": "^25.9.1",
    "@types/react": "^19.2.15",
    "@types/react-dom": "^19.2.3",
    "typescript": "^6.0.3"
  }
}

#!/usr/bin/env python3
"""
Anserini Prebuilt Index Evaluator - Flask Backend
Serves the index catalog, runs retrieval, and evaluates results.
"""

import os
import sys
import json
import subprocess
import logging
from datetime import datetime
from pathlib import Path
from flask import Flask, jsonify, request, send_from_directory, render_template

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler('server.log'),
        logging.StreamHandler(sys.stdout)
    ]
)
logger = logging.getLogger(__name__)

app = Flask(__name__, template_folder='templates', static_folder='static')

# Paths
WORKSPACE_DIR = Path(__file__).parent.resolve()
ANSERINI_JAR = os.environ.get('ANSERINI_JAR', str(WORKSPACE_DIR / 'anserini-2.1.1-fatjar.jar'))
RUNS_DIR = WORKSPACE_DIR / 'runs'
RUNS_DIR.mkdir(exist_ok=True)

# Hardcoded evaluable index -> (topics, qrels) mappings
# These are index names that map to Anserini's known prebuilt index symbols
EVALUABLE_INDEXES = {
    'cacm': {
        'topics': 'cacm',
        'qrels': 'cacm',
        'description': 'CACM Computer Abstract Search'
    }
}

# Metrics supported per qrels set
METRICS_BY_QRELS = {
    'cacm': [
        {'id': 'map', 'label': 'MAP (Mean Average Precision)'},
        {'id': 'P.30', 'label': 'P@30 (Precision at 30)'},
        {'id': 'ndcg_cut.10', 'label': 'NDCG@10'},
        {'id': 'recall.1000', 'label': 'Recall@1000'},
    ]
}

def run_java_command(main_class, args, timeout=300):
    """Run a Java command and return stdout, stderr, and return code."""
    cmd = ['java', '-cp', ANSERINI_JAR, main_class] + args
    logger.info(f"Executing: {' '.join(cmd)}")
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=timeout,
            cwd=str(WORKSPACE_DIR)
        )
        return result.stdout, result.stderr, result.returncode
    except subprocess.TimeoutExpired:
        logger.error(f"Command timed out after {timeout}s: {' '.join(cmd)}")
        return '', f'Command timed out after {timeout}s', -1
    except Exception as e:
        logger.error(f"Error running command: {e}")
        return '', str(e), -1

def fetch_prebuilt_indexes():
    """Fetch prebuilt inverted indexes from Anserini registry."""
    stdout, stderr, code = run_java_command(
        'io.anserini.cli.PrebuiltIndexRegistry',
        ['--type', 'inverted', '--list']
    )
    if code != 0:
        logger.error(f"Failed to fetch indexes: {stderr}")
        return []

    try:
        # Registry outputs JSON array
        indexes = json.loads(stdout)
        logger.info(f"Loaded {len(indexes)} indexes from registry")

        # Mark evaluable indexes
        for idx in indexes:
            idx['evaluable'] = idx['name'] in EVALUABLE_INDEXES
            if idx['evaluable']:
                idx['topics'] = EVALUABLE_INDEXES[idx['name']]['topics']
                idx['qrels'] = EVALUABLE_INDEXES[idx['name']]['qrels']
                idx['description'] = EVALUABLE_INDEXES[idx['name']]['description']
                idx['available_metrics'] = METRICS_BY_QRELS.get(idx['qrels'], [])

        return indexes
    except json.JSONDecodeError as e:
        logger.error(f"Failed to parse index registry JSON: {e}")
        return []

def fetch_topics():
    """Fetch available topics from Anserini registry."""
    stdout, stderr, code = run_java_command(
        'io.anserini.cli.TopicsRegistry',
        ['--list']
    )
    if code != 0:
        logger.error(f"Failed to fetch topics: {stderr}")
        return []

    try:
        # Topics registry outputs JSON array
        topics = json.loads(stdout)
        return topics
    except json.JSONDecodeError as e:
        logger.error(f"Failed to parse topics registry JSON: {e}")
        return []

# Routes
@app.route('/')
def index():
    """Serve the main HTML page."""
    return send_from_directory(app.root_path, 'templates/index.html')

@app.route('/api/health')
def health():
    """Health check endpoint."""
    jar_exists = os.path.exists(ANSERINI_JAR)
    return jsonify({
        'status': 'ok',
        'jar_exists': jar_exists,
        'jar_path': ANSERINI_JAR
    })

@app.route('/api/indexes')
def get_indexes():
    """Return prebuilt indexes from Anserini registry."""
    indexes = fetch_prebuilt_indexes()
    return jsonify(indexes)

@app.route('/api/topics')
def get_topics():
    """Return available topics from Anserini registry."""
    topics = fetch_topics()
    return jsonify(topics)

@app.route('/api/metrics')
def get_metrics():
    """Return available metrics for a given qrels."""
    qrels = request.args.get('qrels', '')
    metrics = METRICS_BY_QRELS.get(qrels, [])
    return jsonify(metrics)

@app.route('/api/evaluate', methods=['POST'])
def evaluate():
    """Run retrieval and evaluation for a selected index/topics/metric combo."""
    data = request.get_json()
    index_name = data.get('index')
    topics_name = data.get('topics')
    qrels_name = data.get('qrels')
    metric = data.get('metric')

    if not all([index_name, topics_name, qrels_name, metric]):
        return jsonify({'error': 'Missing required parameters'}), 400

    # Generate run file with timestamp
    timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    run_file = RUNS_DIR / f'run.{index_name}.{timestamp}.txt'

    logger.info(f"Running evaluation: index={index_name}, topics={topics_name}, qrels={qrels_name}, metric={metric}")

    # Step 1: Run retrieval
    logger.info(f"Running retrieval: SearchCollection -index {index_name} -topics {topics_name} -output {run_file} -hits 1000 -bm25 -threads 1")
    stdout, stderr, code = run_java_command(
        'io.anserini.search.SearchCollection',
        ['-index', index_name, '-topics', topics_name, '-output', str(run_file), '-hits', '1000', '-bm25', '-threads', '1']
    )

    if code != 0:
        logger.error(f"Retrieval failed: {stderr}")
        return jsonify({'error': f'Retrieval failed: {stderr}', 'stderr': stderr}), 500

    logger.info(f"Retrieval complete, run file: {run_file}")

    # Step 2: Run evaluation
    logger.info(f"Running evaluation: TrecEval -c -m {metric} {qrels_name} {run_file}")
    eval_stdout, eval_stderr, eval_code = run_java_command(
        'io.anserini.eval.TrecEval',
        ['-c', '-m', metric, qrels_name, str(run_file)]
    )

    if eval_code != 0:
        logger.error(f"Evaluation failed: {eval_stderr}")
        return jsonify({'error': f'Evaluation failed: {eval_stderr}', 'stderr': eval_stderr}), 500

    # Parse score from evaluation output
    # Format is typically: metric\tall\tscore
    # Note: metric names may have underscores instead of dots in output
    score = None
    # Normalize metric for comparison (replace . with _ and vice versa)
    normalized_metric = metric.replace('.', '_').replace('-', '_')
    for line in eval_stdout.strip().split('\n'):
        parts = line.split('\t')
        if len(parts) >= 3:
            output_metric = parts[0].strip()
            # Check both exact match and normalized match
            if (output_metric == metric or output_metric == normalized_metric) and parts[1] == 'all':
                score = parts[2]
                break

    # Also try without normalization as fallback
    if score is None:
        for line in eval_stdout.strip().split('\n'):
            parts = line.split('\t')
            if len(parts) >= 3 and parts[1] == 'all':
                score = parts[2]
                break

    logger.info(f"Evaluation complete, score: {score}")

    return jsonify({
        'success': True,
        'score': score,
        'metric': metric,
        'index': index_name,
        'topics': topics_name,
        'qrels': qrels_name,
        'run_file': str(run_file),
        'eval_output': eval_stdout,
        'retrieval_output': stdout
    })

@app.route('/api/runs')
def list_runs():
    """List available run files."""
    runs = []
    for f in RUNS_DIR.glob('run.*.txt'):
        runs.append({
            'name': f.name,
            'path': str(f),
            'size': f.stat().st_size,
            'modified': datetime.fromtimestamp(f.stat().st_mtime).isoformat()
        })
    return jsonify(runs)

@app.route('/api/run/<path:filename>')
def get_run(filename):
    """Serve a run file."""
    return send_from_directory(str(RUNS_DIR), filename)

if __name__ == '__main__':
    # Check Java is available
    try:
        result = subprocess.run(['java', '-version'], capture_output=True, text=True)
        logger.info(f"Java version: {result.stderr.splitlines()[0]}")
    except Exception as e:
        logger.error(f"Java not found: {e}")
        sys.exit(1)

    # Check jar exists
    if not os.path.exists(ANSERINI_JAR):
        logger.error(f"Anserini jar not found at: {ANSERINI_JAR}")
        logger.error("Run: curl -fL -o anserini-2.1.1-fatjar.jar https://repo1.maven.org/maven2/io/anserini/anserini/2.1.1/anserini-2.1.1-fatjar.jar")
        sys.exit(1)

    port = int(os.environ.get('PORT', 5555))
    logger.info(f"Starting server on port {port}")
    app.run(host='0.0.0.0', port=port, debug=True, use_reloader=False)

// Anserini Prebuilt Index Evaluator - Frontend JavaScript

const API_BASE = window.location.origin;

let state = {
    indexes: [],
    topics: [],
    selectedIndex: null,
    selectedTopics: null,
    selectedQrels: null,
    selectedMetric: null,
    availableMetrics: [],
    isEvaluating: false,
    results: null
};

// DOM elements
const elements = {
    statusText: document.getElementById('status-text'),
    indexList: document.getElementById('index-list'),
    indexFilter: document.getElementById('index-filter'),
    showEvaluableOnly: document.getElementById('show-evaluable-only'),
    evalPanel: document.getElementById('eval-panel'),
    selectedIndex: document.getElementById('selected-index'),
    selectedTopics: document.getElementById('selected-topics'),
    selectedQrels: document.getElementById('selected-qrels'),
    metricSelect: document.getElementById('metric-select'),
    runBtn: document.getElementById('run-btn'),
    resultsSection: document.getElementById('results-section'),
    resultsContent: document.getElementById('results-content'),
    runFiles: document.getElementById('run-files'),
    loadingOverlay: document.getElementById('loading-overlay'),
    loadingText: document.getElementById('loading-text'),
    anseriniVersion: document.getElementById('anserini-version')
};

// Initialize
async function init() {
    updateStatus('Loading...', null);

    try {
        // Check health
        const health = await fetchAPI('/api/health');
        if (!health.jar_exists) {
            updateStatus('Error: Anserini jar not found at ' + health.jar_path, 'error');
            return;
        }
        updateStatus('Ready - Connected to Anserini fatjar', 'ok');

        // Load indexes and topics in parallel
        const [indexes, topics] = await Promise.all([
            fetchAPI('/api/indexes'),
            fetchAPI('/api/topics')
        ]);

        state.indexes = indexes;
        state.topics = topics;

        renderIndexList();
        await loadRunFiles();

        // Anserini version placeholder
        elements.anseriniVersion.textContent = 'v2.1.1';

    } catch (error) {
        console.error('Init error:', error);
        updateStatus('Error loading data: ' + error.message, 'error');
    }
}

// Fetch helper
async function fetchAPI(endpoint, options = {}) {
    const response = await fetch(API_BASE + endpoint, options);
    if (!response.ok) {
        const error = await response.json().catch(() => ({ error: 'Unknown error' }));
        throw new Error(error.error || `HTTP ${response.status}`);
    }
    return response.json();
}

// Update status bar
function updateStatus(text, status) {
    elements.statusText.textContent = text;
    const statusBar = document.getElementById('status-bar');
    statusBar.className = 'status-bar';
    if (status) {
        statusBar.classList.add(status);
    }
}

// Show/hide loading overlay
function setLoading(show, text = 'Running evaluation...') {
    elements.loadingOverlay.classList.toggle('hidden', !show);
    elements.loadingText.textContent = text;
}

// Render index list
function renderIndexList() {
    const filter = elements.indexFilter.value.toLowerCase();
    const showEvaluableOnly = elements.showEvaluableOnly.checked;

    const filtered = state.indexes.filter(idx => {
        // Filter by text
        if (filter && !idx.name.toLowerCase().includes(filter)) {
            return false;
        }
        // Filter by evaluable
        if (showEvaluableOnly && !idx.evaluable) {
            return false;
        }
        return true;
    });

    if (filtered.length === 0) {
        elements.indexList.innerHTML = '<div class="loading">No indexes match your filter</div>';
        return;
    }

    elements.indexList.innerHTML = filtered.map(idx => {
        const isSelected = state.selectedIndex && state.selectedIndex.name === idx.name;
        const classes = ['index-item'];
        if (isSelected) classes.push('selected');
        if (idx.evaluable) {
            classes.push('evaluable');
        } else {
            classes.push('catalog-only');
        }

        return `
            <div class="${classes.join(' ')}" data-index="${idx.name}">
                <div class="index-name">
                    ${escapeHtml(idx.name)}
                    <span class="index-type">${escapeHtml(idx.type || 'unknown')}</span>
                    <span class="index-badge ${idx.evaluable ? 'evaluable' : 'catalog-only'}">
                        ${idx.evaluable ? 'Evaluable' : 'Catalog'}
                    </span>
                </div>
                ${idx.description ? `<div class="index-description">${escapeHtml(idx.description)}</div>` : ''}
                ${idx.evaluable ? `
                    <div class="index-paired">
                        Topics: <strong>${escapeHtml(idx.topics)}</strong> | 
                        Qrels: <strong>${escapeHtml(idx.qrels)}</strong>
                    </div>
                ` : ''}
            </div>
        `;
    }).join('');

    // Add click handlers
    elements.indexList.querySelectorAll('.index-item').forEach(item => {
        item.addEventListener('click', () => selectIndex(item.dataset.index));
    });
}

// Select an index
function selectIndex(indexName) {
    const index = state.indexes.find(i => i.name === indexName);
    if (!index) return;

    state.selectedIndex = index;

    if (index.evaluable) {
        state.selectedTopics = index.topics;
        state.selectedQrels = index.qrels;
        state.availableMetrics = index.available_metrics || [];

        // Show evaluation panel
        elements.evalPanel.classList.remove('hidden');
        elements.selectedIndex.textContent = index.name;
        elements.selectedTopics.textContent = index.topics;
        elements.selectedQrels.textContent = index.qrels;

        // Populate metrics
        renderMetrics();
    } else {
        elements.evalPanel.classList.add('hidden');
        state.selectedTopics = null;
        state.selectedQrels = null;
        state.availableMetrics = [];
    }

    // Clear previous results
    state.results = null;
    elements.resultsSection.classList.add('hidden');

    renderIndexList();
}

// Render metrics dropdown
function renderMetrics() {
    elements.metricSelect.innerHTML = '<option value="">Select metric...</option>';

    state.availableMetrics.forEach(metric => {
        const option = document.createElement('option');
        option.value = metric.id;
        option.textContent = metric.label;
        elements.metricSelect.appendChild(option);
    });

    // Select nDCG@10 or Recall@1000 by default if available
    const preferredMetrics = ['ndcg_cut.10', 'recall.1000'];
    for (const preferred of preferredMetrics) {
        const option = elements.metricSelect.querySelector(`option[value="${preferred}"]`);
        if (option) {
            option.selected = true;
            state.selectedMetric = preferred;
            break;
        }
    }

    updateRunButton();
}

// Update run button state
function updateRunButton() {
    const canRun = state.selectedIndex && 
                   state.selectedIndex.evaluable && 
                   state.selectedMetric &&
                   !state.isEvaluating;
    elements.runBtn.disabled = !canRun;
}

// Run evaluation
async function runEvaluation() {
    if (!state.selectedIndex || !state.selectedMetric) return;

    state.isEvaluating = true;
    updateRunButton();
    setLoading(true, 'Running retrieval and evaluation...');

    try {
        const response = await fetchAPI('/api/evaluate', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                index: state.selectedIndex.name,
                topics: state.selectedTopics,
                qrels: state.selectedQrels,
                metric: state.selectedMetric
            })
        });

        state.results = response;
        elements.resultsSection.classList.remove('hidden');
        renderResults();
        await loadRunFiles();

    } catch (error) {
        console.error('Evaluation error:', error);
        showError('Evaluation failed: ' + error.message);
    } finally {
        state.isEvaluating = false;
        updateRunButton();
        setLoading(false);
    }
}

// Render results
function renderResults() {
    if (!state.results) {
        elements.resultsContent.innerHTML = '<div class="loading">No results</div>';
        return;
    }

    if (state.results.error) {
        showError(state.results.error);
        return;
    }

    elements.resultsContent.innerHTML = `
        <div class="result-score">${escapeHtml(state.results.score || 'N/A')}</div>
        <div class="result-metric">${escapeHtml(state.results.metric)}</div>
        <div class="result-meta">
            <div class="meta-item">
                <span class="meta-label">Index</span>
                <span class="meta-value">${escapeHtml(state.results.index)}</span>
            </div>
            <div class="meta-item">
                <span class="meta-label">Topics</span>
                <span class="meta-value">${escapeHtml(state.results.topics)}</span>
            </div>
            <div class="meta-item">
                <span class="meta-label">Qrels</span>
                <span class="meta-value">${escapeHtml(state.results.qrels)}</span>
            </div>
            <div class="meta-item">
                <span class="meta-label">Run File</span>
                <span class="meta-value">${escapeHtml(state.results.run_file)}</span>
            </div>
            <div class="meta-item">
                <span class="meta-label">Metric</span>
                <span class="meta-value">${escapeHtml(state.results.metric)}</span>
            </div>
            <div class="meta-item">
                <span class="meta-label">Score</span>
                <span class="meta-value">${escapeHtml(state.results.score)}</span>
            </div>
        </div>
    `;
}

// Show error message
function showError(message) {
    elements.resultsContent.innerHTML = `
        <div class="error-message">${escapeHtml(message)}</div>
    `;
    elements.resultsSection.classList.remove('hidden');
}

// Load run files list
async function loadRunFiles() {
    try {
        const runs = await fetchAPI('/api/runs');

        if (runs.length === 0) {
            elements.runFiles.innerHTML = '<div class="loading">No run files yet</div>';
            return;
        }

        elements.runFiles.innerHTML = runs.map(run => `
            <div class="run-file-item">
                <span class="run-file-name">${escapeHtml(run.name)}</span>
                <span class="run-file-meta">${formatFileSize(run.size)} - ${formatDate(run.modified)}</span>
            </div>
        `).join('');

    } catch (error) {
        console.error('Error loading runs:', error);
        elements.runFiles.innerHTML = '<div class="loading">Error loading run files</div>';
    }
}

// Utility: escape HTML
function escapeHtml(text) {
    if (text === null || text === undefined) return '';
    const div = document.createElement('div');
    div.textContent = String(text);
    return div.innerHTML;
}

// Utility: format file size
function formatFileSize(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

// Utility: format date
function formatDate(isoString) {
    try {
        const date = new Date(isoString);
        return date.toLocaleString();
    } catch {
        return isoString;
    }
}

// Event listeners
elements.indexFilter.addEventListener('input', renderIndexList);
elements.showEvaluableOnly.addEventListener('change', renderIndexList);

elements.metricSelect.addEventListener('change', (e) => {
    state.selectedMetric = e.target.value || null;
    updateRunButton();
});

elements.runBtn.addEventListener('click', runEvaluation);

// Start
init();

