def search_nfcorpus(query, hits=10):
    """Search NFCorpus using the Anserini CLI Search."""
    logger.info(f"Searching NFCorpus for: {query}")

    # Use CLI Search against the index
    stdout, stderr, code = run_java_command(
        'io.anserini.cli.Search',
        ['--index', NFCORPUS_INDEX_PATH, '--query', query, '--hits', str(hits), '--json'],
        timeout=60
    )

    if code != 0:
        logger.error(f"Search failed: {stderr}")
        return {'error': f'Search failed: {stderr}'}

    try:
        results = json.loads(stdout)
        return results
    except json.JSONDecodeError as e:
        logger.error(f"Failed to parse search results: {e}")
        # Try TREC format as fallback
        return {'error': f'Failed to parse results: {e}', 'raw': stdout[:500]}
